const key = env.get('IOT_DEVICE_INGEST_KEY');
const body = msg.payload;
if (!key || msg.req.headers['x-device-key'] !== key) {
    msg.statusCode = 401;
    msg.payload = { message: 'Credencial del dispositivo inválida.' };
    return [null, msg];
}
const validId = typeof body?.deviceId === 'string' && /^[a-zA-Z0-9_-]{2,100}$/.test(body.deviceId);
const validTemperature = Number.isFinite(body?.temperature) && body.temperature >= -80 && body.temperature <= 100;
const validHumidity = Number.isFinite(body?.humidity) && body.humidity >= 0 && body.humidity <= 100;
const validPressure = body?.pressure == null || (Number.isFinite(body.pressure) && body.pressure >= 300 && body.pressure <= 1200);
const validRain = body?.precipitation == null || (Number.isFinite(body.precipitation) && body.precipitation >= 0 && body.precipitation <= 10000);
if (!validId || !validTemperature || !validHumidity || !validPressure || !validRain) {
    msg.statusCode = 400;
    msg.payload = { message: 'La lectura de sensores contiene valores no válidos.' };
    return [null, msg];
}
msg.url = env.get('BACKEND_INGEST_URL');
msg.method = 'POST';
msg.headers = { 'content-type': 'application/json', 'x-ingest-key': key };
msg.payload = {
    deviceId: body.deviceId,
    temperature: body.temperature,
    humidity: body.humidity,
    pressure: body.pressure ?? null,
    precipitation: body.precipitation ?? null
};
return [msg, null];
